// Helper: Format Category (Handles Array, JSON String, and Plain String)
const formatCategory = (val: any): string => {
  if (!val || val === 'null') return '';
  let displayCategory = String(val);
  try {
    // If it's a string that looks like JSON, try to parse it
    const parsed = (typeof val === 'string' && (val.trim().startsWith('[') || val.trim().startsWith('{'))) 
      ? JSON.parse(val) 
      : val;
    
    if (Array.isArray(parsed)) {
      displayCategory = parsed.join('>');
    } else if (typeof parsed === 'object' && parsed !== null) {
      // Fallback for objects if any
      displayCategory = JSON.stringify(parsed);
    } else {
      displayCategory = String(parsed);
    }
  } catch (error) {
    // If parsing fails, it's likely a plain string
    displayCategory = String(val);
  }
  // [Task] UI Polish: Clean trailing symbols (>- , - , >)
  const cleaned = displayCategory
    .replace(/\s*>\s*/g, '>')  // Standardize spaces around '>'
    .replace(/>\s*-\s*$/, '') // Remove trailing '>-' or '> -'
    .replace(/-\s*$/, '')     // Remove trailing '-'
    .replace(/>\s*$/, '')     // Remove trailing '>'
    .trim();
  
  if (cleaned === 'null' || !cleaned) return '';
  return cleaned;
};

// [Task] CRITICAL DATA CLEANUP PIPELINE: COMPACT CATEGORY STRING & END-TRIMMING ENGINE
const sanitizeRepCategoryForExcel = (val: string): string => {
  if (!val) return '';
  // 1. 공백 압축 처리: " > " 기호 좌우의 모든 공백 제거
  let clean = val.replace(/\s*>\s*/g, '>');
  // 2. 우측 끝부분에 불필요한 특수기호 묶음 `>-` 소거
  clean = clean.replace(/>-\s*$/, '');
  return clean;
};

// Helper: Hard-Clean Number (Moved to top level)
const hardCleanNum = (val: any) => {
    if (val === undefined || val === null || val === '') return 0;
    // Remove everything except digits, dots, and minus sign
    const s = String(val).replace(/[^0-9.-]/g, '');
    const n = Number(s);
    return isNaN(n) ? 0 : n;
};

// Helper: Kyiv or Seoul timezone based elapsed days computation to prevent date comparison errors
const getSeoulElapsedDays = (orderAtStr: string | undefined | null): number | null => {
  if (!orderAtStr) return null;
  try {
    const todayKstStr = dayjs().tz('Asia/Seoul').format('YYYY-MM-DD');
    const orderAtKstStr = dayjs(orderAtStr).tz('Asia/Seoul').format('YYYY-MM-DD');
    
    const tDate = dayjs(todayKstStr);
    const oDate = dayjs(orderAtKstStr);
    
    if (!tDate.isValid() || !oDate.isValid()) return null;
    
    const diff = tDate.diff(oDate, 'day');
    return diff < 0 ? 0 : diff;
  } catch (e) {
    console.error("Error calculating SEOUL elapsed days:", e);
    return null;
  }
};

// Helper: Chunk Array for Batch Processing
const chunkArray = <T,>(array: T[], size: number): T[][] => {
  const result: T[][] = [];
  if (!array || array.length === 0) return result;
  for (let i = 0; i < array.length; i += size) {
    result.push(array.slice(i, i + size));
  }
  return result;
};

// Helper: safeParseNumber (NaN Defense)
const safeParseNumber = (val: any) => {
  if (val === null || val === undefined) return 0;
  if (typeof val === 'number') return isNaN(val) ? 0 : val;
  const strVal = String(val).trim();
  if (strVal === '묶음' || strVal === '무료') return 0;
  const cleanedStr = strVal.replace(/,/g, '').replace(/[^-0-9.]/g, '');
  const parsed = Number(cleanedStr);
  return isNaN(parsed) ? 0 : parsed;
};

// Helper: Global Safe Keyword Parser (Defensive Architecture)
const getSafeKeywords = (raw: any): any[] => {
  if (!raw || raw === '-' || raw === 'null') return [];
  
  const filterList = (list: any[]) => {
    return list.filter(item => {
      if (typeof item === 'string') return item.toLowerCase() !== 'null' && item.trim() !== '';
      if (item && typeof item === 'object') {
        const kw = String(item.keyword || item.키워드 || item.word || '').toLowerCase().trim();
        return kw !== 'null' && kw !== '' && kw !== '-';
      }
      return item !== null;
    });
  };

  // 1. If already an array, return it directly with filter
  if (Array.isArray(raw)) return filterList(raw);
  
  // 2. If it's an object (but not an array), wrap it in an array with filter
  if (typeof raw === 'object' && raw !== null) {
    return filterList([raw]);
  }

  let str = String(raw).trim();
  if (!str || str.toLowerCase() === 'null') return [];

  // 3. Strip surrounding quotes and parse
  if (str.startsWith('"') && str.endsWith('"')) {
    try {
      const unquoted = JSON.parse(str);
      if (typeof unquoted === 'string') {
        str = unquoted.trim();
      } else if (Array.isArray(unquoted)) {
        return filterList(unquoted);
      } else if (typeof unquoted === 'object' && unquoted !== null) {
        return filterList([unquoted]);
      }
    } catch (e) {
      str = str.substring(1, str.length - 1).trim();
    }
  }

  // 4. Recursive JSON Handling
  const tryParse = (input: string): any => {
    if (!input.startsWith('[') && !input.startsWith('{')) return null;
    try {
      const p = JSON.parse(input);
      if (typeof p === 'string' && (p.trim().startsWith('[') || p.trim().startsWith('{'))) {
        return JSON.parse(p.trim());
      }
      return p;
    } catch (e) {
      return null;
    }
  };

  const parsed = tryParse(str);
  if (parsed) {
    if (Array.isArray(parsed)) return filterList(parsed);
    if (typeof parsed === 'object' && parsed !== null) return filterList([parsed]);
  }
  
  // 5. Legacy Comma Fallback
  if (!str.startsWith('[') && !str.startsWith('{')) {
    const list = str.split(',')
      .map(k => k.trim())
      .filter(k => k && k.toLowerCase() !== 'null')
      .map(k => ({ keyword: k, inflow: 0, revenue: 0 }));
    return list;
  }
  
  return [];
};

// Helper: Process product data to extract exclusive external channel and inject display_badge_name
const processProductDataWithBadge = (product: any): any => {
  if (!product) return product;

  // 1차 방어 코드
  const rawChannel = product.channel_name;
  let displayBadgeName: string | null = null;

  if (rawChannel && typeof rawChannel === 'string' && rawChannel.trim() !== '' && rawChannel.trim() !== '-') {
    const channels = Array.from(new Set(
      rawChannel.split(',')
        .map(s => s.trim())
        .filter(v => v && v !== '-')
    ));

    if (channels.length === 1) {
      const channelName = channels[0];
      if (!channelName.includes('네이버가격비교') && !channelName.includes('네이버플러스스토어')) {
        displayBadgeName = channelName;
      }
    }
  }

  return {
    ...product,
    display_badge_name: displayBadgeName
  };
};

// Helper: Levenshtein distance calculation
const getLevenshteinDistance = (s1: string, s2: string): number => {
  const m = s1.length;
  const n = s2.length;
  const dp: number[][] = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (s1[i - 1] === s2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1;
      }
    }
  }
  return dp[m][n];
};

// Helper: Check if string is similar (e.g., contains, substring overlap, or low Levenshtein ratio)
const isStringSimilar = (str1: string, str2: string): boolean => {
  const s1 = str1.trim().replace(/\s+/g, '').toLowerCase();
  const s2 = str2.trim().replace(/\s+/g, '').toLowerCase();
  if (!s1 || !s2 || s1 === s2) return false;
  
  // Substring overlap or containment
  if (s1.includes(s2) || s2.includes(s1)) return true;
  
  // Levenshtein distance ratio
  const dist = getLevenshteinDistance(s1, s2);
  const maxLen = Math.max(s1.length, s2.length);
  if (maxLen > 0 && dist / maxLen <= 0.35) return true;
  
  return false;
};

// Helper: Check if two keywords have product counts differing by 2% or less
const checkIsSynonym = (currentItem: RelatedKeyword, list: RelatedKeyword[]): boolean => {
  const aVal = currentItem.keyword;
  const aProd = Number(currentItem.product_count || 0);
  
  return list.some(otherItem => {
    const bVal = otherItem.keyword;
    if (aVal === bVal) return false;
    
    const bProd = Number(otherItem.product_count || 0);
    
    // 1. 형태소/문자열 유사
    if (!isStringSimilar(aVal, bVal)) return false;
    
    // 2. 상품수 데이터 수치 차이 2% 이하
    const diff = Math.abs(aProd - bProd);
    const denom = aProd > 0 ? aProd : (bProd > 0 ? bProd : 1);
    if (diff / denom > 0.02) return false;
    
    return true;
  });
};

// [Task] Supplier Extraction Logic
const extractSupplier = (ownCode: string, mappings: Record<string, string>): string => {
  if (!ownCode) return '미분류';
  
  // STEP A: Only digits -> 도매매
  if (/^\d+$/.test(ownCode)) {
    return '도매매';
  }
  
  // STEP B: Split by _ and match prefix
  const prefix = ownCode.split('_')[0];
  if (mappings[prefix]) {
    return mappings[prefix];
  }
  
  // STEP C: Unclassified
  return '미분류';
};

const accountPriority = ['apachii', 'apasoo', 'dmarkcokr', 'dmarkmall', 'dmarkstore', 'dmarkshop', 'dmark0307'];

const initializeDefaultDateRange = () => {
  const today = new Date();

  // 어제 일자 설정 (조회 종료일: endDate)
  const yesterday = new Date(today);
  yesterday.setDate(today.getDate() - 1);

  // 어제 일자로부터 90일 이전 설정 (조회 시작일: startDate)
  const ninetyDaysAgo = new Date(yesterday);
  ninetyDaysAgo.setDate(yesterday.getDate() - 90);

  const formatDateString = (d: Date) => {
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
  };

  return {
    defaultStartDate: formatDateString(ninetyDaysAgo), // 예: 2026-03-12
    defaultEndDate: formatDateString(yesterday)       // 예: 2026-06-09
  };
};

