const normalizeFuzzy = (val: string | number | undefined | null) => {
  if (val === undefined || val === null) return '';
  return String(val)
    .toLowerCase()
    .replace(/\s+/g, '')
    .replace(/[^a-z0-9가-힣\+]/g, '');
};

const normalizeOptionText = (val: string | number | undefined | null) => {
  if (val === undefined || val === null) return '';
  let str = String(val).trim();
  
  // 1. 접두사 제거 (타입:, 세트:, 사이즈: 등)
  const prefixRegex = /^(제품명|옵션명|타입|세트|사이즈|선택|옵션|색상|컬러|상품추가|상품주문옵션|추가상품)\s*[:：\-\s]\s*/i;
  str = str.replace(prefixRegex, '');

  // 2. 표준어/유사어 변환 (매칭 정밀도)
  str = str.replace(/어댑터/g, '아답터');
  str = str.replace(/아답타/g, '아답터');
  str = str.replace(/아답터/g, '아답터'); // 강제 통일
  str = str.replace(/색상/g, '컬러');
  
  // 3. 중간 라벨 및 구분자 정규화
  str = str.replace(/\s*(타입|세트|사이즈|컬러|색상|옵션|선택)\s*[:：]\s*/gi, ',');
  str = str.replace(/\s*[|/]\s*/g, ','); 

  // 4. 수량 및 가격 정보 꼬리표 제거 (강화된 패턴)
  str = str.replace(/\([+-]?[\d,]*원?\)/g, ''); 
  str = str.replace(/\/[+-]?[\d,]+원/g, '');    
  str = str.replace(/\/\d+(개|알|장|매|세트|p|ea)/gi, ''); 
  str = str.replace(/[-\s]\d+(개|알|장|매|세트|p|ea)$/gi, ''); 
  
  // 5. 특수 케이스: 불필요한 단어 제거 (태영, 00W 등 매칭 방해 요소)
  str = str.replace(/\d+w/gi, ''); // 60W 등 제거
  str = str.replace(/(태영|삼성|엘지|lg)/gi, '');

  // 6. 알파벳, 숫자, 한글, +, -, , 만 유지 (공백 제거 및 소문자화)
  str = str.toLowerCase().replace(/\s+/g, '').replace(/[^a-z0-9가-힣\+\-,]/g, '');
  
  return str.replace(/,+/g, ',').replace(/^,|,$/g, '');
};

const normalizeSkuForMatch = (sku: string) => {
  if (!sku) return '';
  let s = String(sku).trim().toUpperCase();
  // 접두사 제거: OLC_, DMK_, OP+ 등 (2~4자리 대문자 + 기호)
  s = s.replace(/^[A-Z]{2,4}[_+]/, '');
  // 접미사 제거: -1, -2 등
  s = s.split('-')[0];
  return s;
};

// [Fuzzy Match] 단어 순서가 다른 경우에도 매칭 (예: 60W 노트북 아답터 vs 노트북 아답터 60W)
const isOptionMatchFuzzy = (s1: string, s2: string) => {
  if (!s1 || !s2) return s1 === s2;
  if (s1 === s2) return true;
  
  const getCleanWords = (s: string) => s.split(/[,-\s]/).filter(w => w.length > 0 && !/^\d+$/.test(w)).sort();
  const w1 = getCleanWords(s1);
  const w2 = getCleanWords(s2);
  
  if (w1.length === 0 || w2.length === 0) return s1.includes(s2) || s2.includes(s1);
  
  // 한쪽의 모든 키워드가 다른 쪽에 포함되어 있는지 확인
  const set1 = new Set(w1);
  const set2 = new Set(w2);
  const match1 = w1.every(w => set2.has(w) || Array.from(set2).some(sw => sw.includes(w) || w.includes(sw)));
  const match2 = w2.every(w => set1.has(w) || Array.from(set1).some(sw => sw.includes(w) || w.includes(sw)));
  
  return match1 || match2;
};

// [Unification] Real-time Dynamic Date-Matching & Price Binding Helper
const getRealtimePurchaseMatch = (r: ShopmineSale, purchaseRecords: any[], purchaseMap?: Map<string, any[]>) => {
  const rawSku = String(r.seller_product_code || '').trim();
  const normalizedSaleSku = normalizeSkuForMatch(rawSku);
  
  // 1. 주문일 파싱 및 타임스탬프 변환 (오류 방어 로직 포함)
  let orderTime = dayjs(r.order_at).valueOf();
  if (isNaN(orderTime)) {
    // 엑셀 AM/PM 포맷 대응을 위한 정규화 (예: 2026-04-29 2:16:14 PM)
    const dStr = String(r.order_at || '');
    const normalizedDateStr = dStr.replace(/([AP]M)$/i, ' $1').trim();
    orderTime = dayjs(normalizedDateStr).valueOf();
  }
  
  if (isNaN(orderTime)) return null;

  const normalizedSaleOptions = normalizeOptionText(r.options || '');

  try {
    // 사입/위탁 여부 판별
    const normalizedSupplier = String(r.supplier || '').trim();
    const normalizedVendor = String((r as any).vendor_name || '').trim();
    const normalizedManufacturer = String((r as any).manufacturer || '').trim();
    
    const isSaipBySale = (
      rawSku.toUpperCase().includes('OP+') || 
      normalizedSupplier === '사입' || 
      normalizedVendor === '사입' ||
      normalizedManufacturer === '사입'
    );

    // 2. 상품군별 타겟 날짜 필드 분기 및 정밀 타임스탬프 변환
    const getCompareTimestamp = (pr: any) => {
      const prVendor = String(pr.vendor_name || '').trim();
      const isSaipRecord = (isSaipBySale || prVendor === '사입');
      
      const dateVal = isSaipRecord ? pr.created_at : pr.record_date;
      // 기준일이 없는 경우 수집일(collectedAt) 등으로 대체하여 정합성 유지
      const finalDate = dateVal || pr.record_date || pr.created_at || pr.collectedAt;
      const ts = dayjs(finalDate).valueOf();
      return isNaN(ts) ? 0 : ts;
    };

    // 3. SKU & Option 매칭 후보군 추출
    const skuCandidates = purchaseMap 
      ? (purchaseMap.get(`NSKU_${normalizedSaleSku}`) || []) 
      : purchaseRecords.filter(pr => normalizeSkuForMatch(pr.internal_sku || pr.productCode) === normalizedSaleSku);

    let resolvedBarcode = String(r.option_barcode || '').trim();

    if (skuCandidates.length > 0) {
      let candidates = skuCandidates;
      if (normalizedSaleOptions) {
        candidates = skuCandidates.filter(pr => {
          const prOption = pr._normalizedOption || normalizeOptionText(pr.order_option || '');
          return isOptionMatchFuzzy(normalizedSaleOptions, prOption);
        });
      }

      const allValidRecords = candidates.filter(pr => getCompareTimestamp(pr) > 0);
      
      if (allValidRecords.length > 0) {
        // 3. 엄격한 내림차순 정렬 및 타임라인 컷오프
        const sortedRecords = [...allValidRecords].sort((a, b) => getCompareTimestamp(b) - getCompareTimestamp(a));
        let bestMatch = sortedRecords.find(pr => getCompareTimestamp(pr) <= orderTime);

        // 4. Fallback Logic: 주문일 이전 데이터가 아예 없을 경우 시스템상 가장 과거/최초 기록 적용 (소급 매칭)
        if (!bestMatch) {
          bestMatch = sortedRecords[sortedRecords.length - 1];
        }

        if (bestMatch) {
          if (!resolvedBarcode && bestMatch.option_barcode) {
            resolvedBarcode = String(bestMatch.option_barcode).trim();
            r.option_barcode = resolvedBarcode;
          }

          // 5. 데이터 명시적 할당 및 1원 단위 반올림 적용
          const finalPrice = Math.round(Number(bestMatch.unit_price || bestMatch.purchasePrice || 0));
          const finalFee = Math.round(Number(bestMatch.shipping_fee || 0));
          
          r.purchase_price = finalPrice;
          if ('unit_price' in r) (r as any).unit_price = finalPrice;
          if ('latestFee' in r) (r as any).latestFee = finalFee;

          const isSaipActual = isSaipBySale || String(bestMatch.vendor_name || '').trim() === '사입';
          if (!isSaipActual) {
            return bestMatch;
          }
        }
      }
    }

    // 4. 바코드 기반 시계열 매칭 (사입 상품 필수 로직)
    if (resolvedBarcode) {
      let priceCandidates: any[] = [];
      if (purchaseMap && purchaseMap.has(`BC_${resolvedBarcode}`)) {
        priceCandidates = purchaseMap.get(`BC_${resolvedBarcode}`) || [];
      } else {
        priceCandidates = purchaseRecords.filter(pr => String(pr.option_barcode || '').trim() === resolvedBarcode);
      }

      const withPrice = priceCandidates.filter(pr => getCompareTimestamp(pr) > 0 && Number(pr.unit_price || pr.purchasePrice || 0) > 0);
      
      if (withPrice.length > 0) {
        // 3. 엄격한 내림차순 정렬 및 타임라인 컷오프
        const sortedPriceRecords = [...withPrice].sort((a, b) => getCompareTimestamp(b) - getCompareTimestamp(a));
        let match = sortedPriceRecords.find(pr => getCompareTimestamp(pr) <= orderTime);
        
        // 4. Fallback Logic
        if (!match) {
          match = sortedPriceRecords[sortedPriceRecords.length - 1];
        }

        if (match) {
          // 5. 데이터 명시적 할당 및 1원 단위 반올림 적용
          const finalPrice = Math.round(Number(match.unit_price || match.purchasePrice || 0));
          const finalFee = Math.round(Number(match.shipping_fee || 0));
          
          r.purchase_price = finalPrice;
          if ('unit_price' in r) (r as any).unit_price = finalPrice;
          if ('latestFee' in r) (r as any).latestFee = finalFee;
          return match;
        }
      }
    }

  } catch (err) {
    console.warn('[MatchingError]', err);
  }
  
  r.purchase_price = 0;
  return null;
};

const cleanComplexOption = (rawOption: any): string => {
  if (!rawOption) return '';
  try {
    let text = String(rawOption)
       .replace(/\s*\([-+]?\s*\d+원?\s*\)\s*/g, ' ')
       .replace(/\s*\([^\w가-힣]*\)\s*/g, ' ')
       .replace(/\s*[-+]\s*\d+원\s*/g, ' ');

    const parts = text.split('/').map(p => p.trim());
    const cleanedParts: string[] = [];

    for (let part of parts) {
      if (/^\+?\d+원$/.test(part) || /^\d+(개|알|장|매|세트|p)$/i.test(part)) continue;
      
      let cleaned = part.replace(/^(타입|세트|사이즈|선택|옵션|색상|건전지)\s*[:：]\s*/, '');
      cleaned = cleaned.replace(/-\s*\d+(개|알|장|매|세트|p)$/i, '');
      cleaned = cleaned.trim();

      if (cleaned === 'ON') cleaned = 'ON (푸시)';
      if (cleaned === 'LOCK') cleaned = 'LOCK (락)';
      if (cleaned === '와인색') cleaned = '와인';
      if (cleaned === '엘로우') cleaned = '옐로우';
      
      cleaned = cleaned.replace('마이크케이블 55잭 XLR 5m', 'XLR 케이블 55 5m');
      cleaned = cleaned.replace('1P 드럼세탁기', '드럼세탁기');
      cleaned = cleaned.replace('AA2알', 'AA');
      cleaned = cleaned.replace(/DC 7\.5V1A 어댑터 태영/, '아답터 7.5V1A');
      cleaned = cleaned.replace(/DC 9V2A 어댑터 태영/, '아답터 9V2A');

      if (cleaned) cleanedParts.push(cleaned);
    }
    return cleanedParts.join(',');
  } catch (e) {
    return String(rawOption || '');
  }
};

const standardizeOptionName = (code: string, options: string) => {
  if (!options) return '';
  let standardized = options;
  
  const tiers = standardized.split('/').map(t => {
    let part = t.trim();
    
    // [Task] 타입: 접두사 및 프로모션 텍스트 제거 보완
    part = part.replace(/타입\s*[:：]/gi, '');
    part = part.replace(/\(개당\s*\d+원\)/g, '');
    part = part.replace(/❤[^❤]+❤\s*:/g, '');
    part = part.replace(/❤[^❤]+❤/g, '');
    part = part.replace(/\[(\d+\+\d+)\]/g, '$1');
    part = part.replace(/\[\d+개\]/g, ''); 
    part = part.replace(/\s*\(\d+개\)\s*[\d,]+원\s*/g, '');
    part = part.replace(/:/g, ' '); 
    
    // Keyword Extraction (Keeping only meaningful alphanumeric/korean chunks)
    const chunks = (part.match(/[a-zA-Z0-9\+]+|[가-힣]+/g) || []) as string[];
    
    const keywords: string[] = [];
    const seen = new Set<string>();

    chunks.forEach(ck => {
      const normalized = ck.toLowerCase();
      if (seen.has(normalized)) return;
      seen.add(normalized);
      keywords.push(normalized);
    });

    // Reconstruct keywords sorted (model info like 01, 1m first then Korean)
    const modelKws = keywords.filter(k => /^[a-z0-9\+]+$/.test(k)).sort();
    const koreanKws = keywords.filter(k => /^[가-힣]+$/.test(k)).sort();

    return [...modelKws, ...koreanKws].join(' ');
  });
  
  return tiers.filter(t => t !== '').join(', ');
};

const normalizeWholesaleOption = (rawText: string) => {
  let text = String(rawText || '').trim();

  // [Task] 보완된 정규식 반영 (사용자 지정 하이픈/슬래시 뒤 수량 완벽 제거)
  text = text.replace(/[-\/]\s*\d+\s*개/g, '');
  text = text.replace(/\(\+\s*\d+\s*원\)/g, '');

  // 1단계: 각종 접두사 제거 (기존 로직 유지)
  text = text.replace(/^(?:옵션|선택사항|타입|세트|색상|사이즈)\s*:\s*/g, '');
  text = text.replace(/^[❤⭐✨🔥✅📢|\[\]\(\)\s*]+[:\s]*/g, ''); 

  // 2단계: 기타 꼬리표 패턴 처리
  text = text.replace(/\/\s*[0-9,]+\s*원\s*\/\s*[0-9]+\s*[개ea]\s*$/gi, '');
  text = text.replace(/\s*[-/]\s*[0-9,]+\s*(?:개|ea)\s*$/gi, ''); 
  text = text.replace(/\s*\(\s*[+-]?\s*[0-9,]+\s*원\s*\)\s*$/g, '');

  // 3단계: 대괄호/소괄호 내 부가정보 제거
  text = text.replace(/[\[\(][^\]\)]*[가-힣]+[^\]\)]*[\]\)]/g, '');

  // 4단계: 옵션을 구분하는 슬래시(/)를 쉼표(,)로 치환
  text = text.replace(/\s*\/\s*/g, ',');

  // 5단계: 불필요한 공백 제거
  return text.replace(/\s+/g, ' ').trim();
};

const purifyText = (val: string) => {
  if (!val) return '';
  return String(val)
    .replace(/\s+/g, '')
    .replace(/\([^)]*\)|\[[^\]]*\]/g, '')
    .replace(/[^a-zA-Z0-9가-힣]/g, '');
};

const normalizeForCompare = (str: string) => (str || '').replace(/[^가-힣a-zA-Z0-9]/g, '');

// [OP+ Validation Tests]

const getQuantityMultiplier = (options: string) => {
  if (!options) return 1;
  // Patterns: 1+1, 2+2, 총n개
  const plusMatch = options.match(/(\d+)\+(\d+)/);
  if (plusMatch) return parseInt(plusMatch[1]) + parseInt(plusMatch[2]);
  
  const totalMatch = options.match(/총\s*(\d+)\s*개/);
  if (totalMatch) return parseInt(totalMatch[1]);
  
  return 1;
};

