  const fetchUploadHistory = async () => {
    try {
      const { data, error } = await supabase
        .from('statistics_history')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      
      // Map DB columns to UI state structure
      const mapped = (data || []).map(item => {
        const parts = (item.stats_period || '').split('~');
        const endDate = parts.length > 1 ? parts[1].trim() : '';
        return {
          id: item.id,
          account: item.account,
          mall: item.mall,
          uploadedAt: dayjs(item.created_at).format('YYYY-MM-DD'),
          statsPeriod: item.stats_period,
          recordCount: item.record_count,
          endDate: endDate,
          createdAt: item.created_at
        };
      });

      // 정렬 위계 규칙: '조회 기간 종료일(end_date)' 및 '최근 업데이트 일자(createdAt)' 기준 엄격한 내림차순 정렬
      mapped.sort((a, b) => {
        const dateA = a.endDate ? dayjs(a.endDate).valueOf() : 0;
        const dateB = b.endDate ? dayjs(b.endDate).valueOf() : 0;
        if (dateB !== dateA) {
          return dateB - dateA; // end_date 내림차순
        }
        const timeA = a.createdAt ? dayjs(a.createdAt).valueOf() : 0;
        const timeB = b.createdAt ? dayjs(b.createdAt).valueOf() : 0;
        return timeB - timeA; // 최신 생성일시 내림차순
      });

      setUploadHistory(mapped);
    } catch (e) {
      console.error("Failed to fetch upload history from DB:", e);
    }
  };

