  const [salesDateFilter, setSalesDateFilter] = useState<'today' | '7days' | '30days' | 'custom'>('custom');
  const [customStartDate, setCustomStartDate] = useState(() => initializeDefaultDateRange().defaultStartDate);
  const [customEndDate, setCustomEndDate] = useState(() => initializeDefaultDateRange().defaultEndDate);

  // New Sales Filters
