  const [categoryBadgeRefreshTrigger, setCategoryBadgeRefreshTrigger] = useState(0);

  useEffect(() => {
    const fetchCategoryTermsForBadge = async () => {
      const activeCat = (categoryInput || statsCategory || '').trim();
      if (!activeCat) {
        setActiveCategoryTerms([]);
        return;
      }

      try {
        // 1단계: 카테고리 1:1 매칭 (정확히 일치하는 행 조회)
        const { data, error } = await supabase
          .from('search_csv_keywords')
          .select('category_terms')
          .eq('representative_category', activeCat);

        if (error) {
          console.error('[Category Badge Match Fetch Error]:', error);
          setActiveCategoryTerms([]);
          return;
        }

        if (data && data.length > 0) {
          // 2단계: 텀 비교 분석 및 안전 파싱
          const allTerms: string[] = [];
          data.forEach(row => {
            if (row.category_terms) {
              let parsed: string[] = [];
              if (Array.isArray(row.category_terms)) {
                parsed = row.category_terms.map(t => String(t).trim()).filter(Boolean);
              } else if (typeof row.category_terms === 'string') {
                const trimmed = row.category_terms.trim();
                if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
                  try {
                    const decoded = JSON.parse(trimmed);
                    if (Array.isArray(decoded)) {
                      parsed = decoded.map(t => String(t).trim()).filter(Boolean);
                    }
                  } catch (e) {
                    parsed = trimmed.split(/[\s,]+/).map(t => t.trim()).filter(Boolean);
                  }
                } else {
                  parsed = trimmed.split(/[\s,]+/).map(t => t.trim()).filter(Boolean);
                }
              }
              parsed.forEach(term => {
                if (term && !allTerms.includes(term)) {
                  allTerms.push(term);
                }
              });
            }
          });
          setActiveCategoryTerms(allTerms);
        } else {
          setActiveCategoryTerms([]);
        }
      } catch (err) {
        console.error('[Category Badge Match Exception]:', err);
        setActiveCategoryTerms([]);
      }
    };

    fetchCategoryTermsForBadge();
  }, [categoryInput, statsCategory, categoryBadgeRefreshTrigger]);

  // [Category SEO Parameters States]
