  // [Category SEO Parameters Modes Calculation]
  useEffect(() => {
    const calculateModes = async () => {
      try {
        const { data, error } = await supabase
          .from('search_csv_keywords')
          .select('representative_category, keyword_value_order');
        
        if (error) {
          console.error('[SEO Mode Count Fetch Error]:', error);
          return;
        }

        if (data && data.length > 0) {
          // 중복을 제거한 representative_category(대표 카테고리) 값을 기준으로 데이터를 필터링 및 그룹화
          const uniqueCategoryMap = new Map<string, any>();
          
          data.forEach(row => {
            const cat = (row.representative_category || '').trim();
            if (!cat) return; // 대표 카테고리가 없는 빈 값은 통계에서 제외
            
            // 해당 카테고리에 대해 최초로 발견된 유효한 keyword_value_order 데이터를 매핑
            if (!uniqueCategoryMap.has(cat)) {
              uniqueCategoryMap.set(cat, row.keyword_value_order);
            }
          });

          const termCounts: Record<string, number> = {};
          const dupeCounts: Record<string, number> = {};

          uniqueCategoryMap.forEach((arr) => {
            if (!arr) return;
            
            let parsedArr: any[] = [];
            if (Array.isArray(arr)) {
              parsedArr = arr;
            } else if (typeof arr === 'string') {
              try {
                parsedArr = JSON.parse(arr);
              } catch {
                // ignore
              }
            }

            if (Array.isArray(parsedArr) && parsedArr.length > 0) {
              const tc = String(parsedArr[0] || '').trim();
              if (tc && tc !== '0') {
                termCounts[tc] = (termCounts[tc] || 0) + 1;
              }

              if (parsedArr.length > 1) {
                const dcRaw = String(parsedArr[1] || '').trim();
                const numericPart = dcRaw.replace(/기본\s*1\s*추가\s*/g, '').trim();
                if (numericPart && numericPart !== '0') {
                  dupeCounts[numericPart] = (dupeCounts[numericPart] || 0) + 1;
                }
              }
            }
          });

          let maxTc = '2';
          let maxTcCount = 0;
          Object.entries(termCounts).forEach(([val, count]) => {
            if (count > maxTcCount) {
              maxTcCount = count;
              maxTc = val;
            }
          });

          let maxDc = '10';
          let maxDcCount = 0;
          Object.entries(dupeCounts).forEach(([val, count]) => {
            if (count > maxDcCount) {
              maxDcCount = count;
              maxDc = val;
            }
          });

          setModeTermCount(maxTc);
          setModeDupeCount(maxDc);
        }
      } catch (err) {
        console.error('[calculateModes Exception]:', err);
      }
    };

    calculateModes();
  }, [categoryInput, statsCategory]);

  // [Category SEO Parameters Load Effect]
  useEffect(() => {
    const fetchCategorySEOData = async () => {
      const activeSanitizedCategory = (categoryInput || '').replace(/\s+/g, '');
      // [강력한 가드] 성과 키워드(manualMainKeyword)가 DB의 메인 keyword 컬럼을 오염시키지 못하도록 차단하고,
      // 우측 화면 분석 결과의 기준점이자 마스터 키 역할을 하는 순수 메인 분석 대상 키워드 원본 변수를 사용합니다.
      const currentKeyword = (mainKeywordInfo?.displayStatsKeyword || (matchedOrderData as any)?.keyword || '').trim();
      if (!activeSanitizedCategory && !currentKeyword) {
        setCategoryTermInput('');
        setOptimalTermCountInput('');
        setOptimalDuplicateCountInput('');
        return;
      }
      
      try {
        let matchedRow: any = null;

        // 1단계: 카테고리 매칭 조회
        if (activeSanitizedCategory) {
          const possibleCategories = Array.from(new Set([
            activeSanitizedCategory,
            categoryInput || '',
            (statsCategory || '').replace(/\s+/g, ''),
            statsCategory || ''
          ])).filter(Boolean);
          
          const { data, error } = await supabase
            .from('search_csv_keywords')
            .select('category_terms, keyword_value_order')
            .in('representative_category', possibleCategories);
          if (!error && data && data.length > 0) {
            matchedRow = data.find(row => row.category_terms || row.keyword_value_order) || data[0];
          }
        }

        // 2단계: 카테고리 결과가 없거나 데이터가 비어있는 경우 현재 활성 키워드로 폴백 조회
        if (!matchedRow && currentKeyword) {
          const { data, error } = await supabase
            .from('search_csv_keywords')
            .select('category_terms, keyword_value_order')
            .eq('keyword', currentKeyword);
            
          if (!error && data && data.length > 0) {
            matchedRow = data[0];
          }
        }
        
        if (matchedRow) {
          let termsStr = '';
          if (Array.isArray(matchedRow.category_terms)) {
            termsStr = matchedRow.category_terms.join(', ');
          } else if (typeof matchedRow.category_terms === 'string') {
            try {
              const parsed = JSON.parse(matchedRow.category_terms);
              termsStr = Array.isArray(parsed) ? parsed.join(', ') : matchedRow.category_terms;
            } catch {
              termsStr = matchedRow.category_terms;
            }
          }
          setCategoryTermInput(termsStr);
          
          let termCount = '';
          let dupeCount = '';
          if (Array.isArray(matchedRow.keyword_value_order)) {
            termCount = String(matchedRow.keyword_value_order[0] || '');
            dupeCount = String(matchedRow.keyword_value_order[1] || '');
          } else if (typeof matchedRow.keyword_value_order === 'string') {
            try {
              const parsed = JSON.parse(matchedRow.keyword_value_order);
              if (Array.isArray(parsed)) {
                termCount = String(parsed[0] || '');
                dupeCount = String(parsed[1] || '');
              } else {
                termCount = matchedRow.keyword_value_order;
              }
            } catch {
              termCount = matchedRow.keyword_value_order;
            }
          } else if (typeof matchedRow.keyword_value_order === 'number') {
            termCount = String(matchedRow.keyword_value_order);
          }
          
          setOptimalTermCountInput(termCount);
          const numericPart = dupeCount.replace(/기본\s*1\s*추가\s*/g, '').trim();
          setOptimalDuplicateCountInput(numericPart);
        } else {
          setCategoryTermInput('');
          setOptimalTermCountInput('');
          setOptimalDuplicateCountInput('');
        }
      } catch (fetchErr) {
        console.error("[Client SEO Fetch Exception] Gracefully caught:", fetchErr);
      }
    };
    
    fetchCategorySEOData();
  }, [categoryInput, statsCategory, mainKeywordInfo?.displayStatsKeyword, (matchedOrderData as any)?.keyword]);

  // [Category SEO Parameters Save Action]
  const handleSaveCategoryMetrics = async () => {
    const activeSanitizedCategory = (categoryInput || '').replace(/\s+/g, '');
    const currentKeyword = (mainKeywordInfo?.displayStatsKeyword || (matchedOrderData as any)?.keyword || '').trim();
    if (!activeSanitizedCategory && !currentKeyword) {
      alert('저장할 카테고리 정보 또는 활성 키워드가 없습니다.');
      return;
    }
    
    setIsSyncingCategoryMetrics(true);
    try {
      const finalTermsArray = categoryTermInput
         ? categoryTermInput.split(/[\s,]+/).map(t => t.trim()).filter(Boolean)
         : [];
         
      const rawDupeVal = String(optimalDuplicateCountInput || '0').trim();
      const formattedDupeVal = rawDupeVal.startsWith('기본1 추가')
        ? rawDupeVal
        : `기본1 추가${rawDupeVal}`;
         
      const finalCountsArrayMatched = [
        String(optimalTermCountInput || '0').trim(),
        formattedDupeVal
      ];

      // 1. 카테고리 기준 일괄 업데이트 (카테고리 정보가 있는 경우)
      if (activeSanitizedCategory) {
        const possibleCategories = Array.from(new Set([
          activeSanitizedCategory,
          categoryInput || '',
          (statsCategory || '').replace(/\s+/g, ''),
          statsCategory || ''
        ])).filter(Boolean);
        
        const { error: updateError } = await supabase
          .from('search_csv_keywords')
          .update({
            category_terms: finalTermsArray,
            keyword_value_order: finalCountsArrayMatched,
            updated_at: new Date().toISOString()
          })
          .in('representative_category', possibleCategories);
          
        if (updateError) {
          console.error('[SEO Save Category Update error]:', updateError);
        }
      }

      // 2. 현재 활성 키워드 기준 핀포인트 업서트
      if (currentKeyword) {
        const { data: existingRows, error: fetchError } = await supabase
          .from('search_csv_keywords')
          .select('*')
          .eq('keyword', currentKeyword);

        if (!fetchError) {
          const existingRow = existingRows?.[0] || {};
          const upsertPayload = {
            ...existingRow,
            keyword: currentKeyword,
            representative_category: categoryInput || statsCategory || existingRow.representative_category || null,
            category_terms: finalTermsArray,
            keyword_value_order: finalCountsArrayMatched,
            updated_at: new Date().toISOString()
          };

          const { error: upsertError } = await supabase
            .from('search_csv_keywords')
            .upsert([upsertPayload]);

          if (upsertError) {
            console.error('[SEO Save Keyword Upsert error]:', upsertError);
          }
        }
      }
      
      setCategoryBadgeRefreshTrigger(prev => prev + 1);
      alert('카테고리 가점 매커니즘이 성공적으로 DB에 동기화되었습니다.');
    } catch (saveErr: any) {
      console.error('[SEO Save Exception] Gracefully caught:', saveErr);
      alert('가점 매커니즘 저장 중 오류가 발생했습니다: ' + (saveErr.message || 'Unknown error'));
    } finally {
      setIsSyncingCategoryMetrics(false);
    }
  };

  // Helper: Calculate Byte Length (EUC-KR approximation)
  const getByteLength = (s: string) => {
    let b = 0;
    for (let i = 0; i < s.length; i++) {
      const c = s.charCodeAt(i);
      b += (c >> 7) ? 2 : 1;
    }
    return b;
  };

