                                    <Line yAxisId="right" type="monotone" dataKey="orderCount" name="orderCount" stroke="#10b981" strokeWidth={1.5} strokeDasharray="5 5" dot={{ r: 3, fill: '#10b981' }} isAnimationActive={false} />
